import java.util.*; abstract class Worker08{String name;double salary;Worker08(String n,double s){name=n;salary=s;}abstract double bonus();} class FullTime08 extends Worker08{FullTime08(String n,double s){super(n,s);}double bonus(){return salary*.1;}} class PartTime08 extends Worker08{PartTime08(String n,double s){super(n,s);}double bonus(){return salary*.05;}} class Intern08 extends Worker08{Intern08(String n,double s){super(n,s);}double bonus(){return 2000;}} public class Week08Problem04{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=Integer.parseInt(s.nextLine().trim());double total=0;for(int i=0;i<n;i++){String[]p=s.nextLine().trim().split("\\s+");String t=p[0].toUpperCase();Worker08 w=t.equals("FULLTIME")?new FullTime08(p[1],Double.parseDouble(p[2])):t.equals("PARTTIME")?new PartTime08(p[1],Double.parseDouble(p[2])):new Intern08(p[1],Double.parseDouble(p[2]));System.out.printf("%s: %.2f%n",w.name,w.bonus());total+=w.bonus();}System.out.printf("Total bonus: %.2f%n",total);}}